# Analyze baseline failures: cut-off rate, word frequencies in cut-off vs finished
import json, re, collections
base = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
cut = [r for r in base if r['finish']=='length']
fin = [r for r in base if r['finish']=='stop']
print('cut', len(cut), 'fin', len(fin), 'correct cut', sum(r['correct'] for r in cut), 'correct fin', sum(r['correct'] for r in fin))
# words opening a line
word_cut = collections.Counter(); word_fin = collections.Counter()
tot_cut = sum(r['tokens'] for r in cut); tot_fin = sum(r['tokens'] for r in fin)
for r in cut:
    for line in r['text'].split('\n'):
        m = re.match(r'\s*([A-Za-z]+)', line)
        if m: word_cut[m.group(1)] += 1
for r in fin:
    for line in r['text'].split('\n'):
        m = re.match(r'\s*([A-Za-z]+)', line)
        if m: word_fin[m.group(1)] += 1
rate_cut = {w: c/tot_cut*1000 for w,c in word_cut.items()}
rate_fin = {w: c/tot_fin*1000 for w,c in word_fin.items()}
allw = set(rate_cut)|set(rate_fin)
diffs = sorted(allw, key=lambda w: rate_cut.get(w,0)-rate_fin.get(w,0), reverse=True)
for w in diffs[:15]:
    print(f'{w:12s} cut {rate_cut.get(w,0):.3f} fin {rate_fin.get(w,0):.3f}')
print()
for w in sorted(allw, key=lambda w: rate_fin.get(w,0)-rate_cut.get(w,0), reverse=True)[:10]:
    print(f'{w:12s} cut {rate_cut.get(w,0):.3f} fin {rate_fin.get(w,0):.3f}')

