# Scan ALL tensors: load() vs load_original()
diffs = []
for n in NAMES:
    try:
        a = load(n); b = load_original(n)
    except Exception as e:
        diffs.append((n, 'ERR', str(e)[:80])); continue
    if a.shape != b.shape:
        diffs.append((n, 'SHAPE', (a.shape, b.shape))); continue
    d = (a-b).abs().max().item()
    if d > 0: diffs.append((n, 'DIFF', d))
print('differing tensors:', len(diffs))
for d in diffs: print(d)
